package com.agenda.clinica.controller;
import com.agenda.clinica.dto.request.CitaRequest; import com.agenda.clinica.dto.response.CitaResponse; import com.agenda.clinica.service.CitaService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api") public class CitaController { private final CitaService service; public CitaController(CitaService s){service=s;} @PostMapping("/public/citas") public CitaResponse reservar(@Valid @RequestBody CitaRequest r){return service.crear(r);} @GetMapping("/admin/citas") public List<CitaResponse> agenda(@RequestParam LocalDate desde,@RequestParam LocalDate hasta){return service.agenda(desde,hasta);} @PatchMapping("/admin/citas/{id}/estado") public CitaResponse estado(@PathVariable Long id,@RequestBody Map<String,String> body){return service.cambiarEstado(id,body.get("estado"));} }
